pub type Document = {
  title: Str;
  content: Vec[Str];
} derive[Clone]

fn duplicate_and_append(original: &Document, line: Str) -> Document {
  var copy = original.clone();
  copy.content.push(line);
  return copy;
}

fn main() -> Int {
  let original = Document{ title: "Draft", content: Vec[Str]() };
  original.content.push("Line 1");
  let copy = duplicate_and_append(&original, "Line 2");
  return copy.content.len();
}
